// Distinguishes the different kinds of TypeDefs.
type TypeDefKind = core.TypeDefKind

const (
	// A boolean value.
	TypeDefKindBoolean TypeDefKind = core.TypeDefKindBoolean

	// A boolean value.
	TypeDefKindBooleanKind TypeDefKind = core.TypeDefKindBooleanKind

	// A GraphQL enum type and its values
	//
	// Always paired with an EnumTypeDef.
	TypeDefKindEnum TypeDefKind = core.TypeDefKindEnum

	// A GraphQL enum type and its values
	//
	// Always paired with an EnumTypeDef.
	TypeDefKindEnumKind TypeDefKind = core.TypeDefKindEnumKind

	// A float value.
	TypeDefKindFloat TypeDefKind = core.TypeDefKindFloat

	// A float value.
	TypeDefKindFloatKind TypeDefKind = core.TypeDefKindFloatKind

	// A graphql input type, used only when representing the core API via TypeDefs.
	TypeDefKindInput TypeDefKind = core.TypeDefKindInput

	// A graphql input type, used only when representing the core API via TypeDefs.
	TypeDefKindInputKind TypeDefKind = core.TypeDefKindInputKind

	// An integer value.
	TypeDefKindInteger TypeDefKind = core.TypeDefKindInteger

	// An integer value.
	TypeDefKindIntegerKind TypeDefKind = core.TypeDefKindIntegerKind

	// Always paired with an InterfaceTypeDef.
	//
	// A named type of functions that can be matched+implemented by other objects+interfaces.
	TypeDefKindInterface TypeDefKind = core.TypeDefKindInterface

	// Always paired with an InterfaceTypeDef.
	//
	// A named type of functions that can be matched+implemented by other objects+interfaces.
	TypeDefKindInterfaceKind TypeDefKind = core.TypeDefKindInterfaceKind

	// Always paired with a ListTypeDef.
	//
	// A list of values all having the same type.
	TypeDefKindList TypeDefKind = core.TypeDefKindList

	// Always paired with a ListTypeDef.
	//
	// A list of values all having the same type.
	TypeDefKindListKind TypeDefKind = core.TypeDefKindListKind

	// Always paired with an ObjectTypeDef.
	//
	// A named type defined in the GraphQL schema, with fields and functions.
	TypeDefKindObject TypeDefKind = core.TypeDefKindObject

	// Always paired with an ObjectTypeDef.
	//
	// A named type defined in the GraphQL schema, with fields and functions.
	TypeDefKindObjectKind TypeDefKind = core.TypeDefKindObjectKind

	// A scalar value of any basic kind.
	TypeDefKindScalar TypeDefKind = core.TypeDefKindScalar

	// A scalar value of any basic kind.
	TypeDefKindScalarKind TypeDefKind = core.TypeDefKindScalarKind

	// A string value.
	TypeDefKindString TypeDefKind = core.TypeDefKindString

	// A string value.
	TypeDefKindStringKind TypeDefKind = core.TypeDefKindStringKind

	// A special kind used to signify that no value is returned.
	//
	// This is used for functions that have no return value. The outer TypeDef specifying this Kind is always Optional, as the Void is never actually represented.
	TypeDefKindVoid TypeDefKind = core.TypeDefKindVoid

	// A special kind used to signify that no value is returned.
	//
	// This is used for functions that have no return value. The outer TypeDef specifying this Kind is always Optional, as the Void is never actually represented.
	TypeDefKindVoidKind TypeDefKind = core.TypeDefKindVoidKind
)

func Ref[T Loadable[T]](c *Client, id ID) T {
	return core.Ref[T](c.Query, id)
}

func Load[T Loadable[T]](ctx context.Context, c *Client, id ID) (T, error) {
	return core.Load[T](ctx, c.Query, id)
}

func Tracer() trace.Tracer {
	return core.Tracer()
}

// SetMarshalContext is a hack that lets us set the ctx to use for
// MarshalJSON implementations that get an object's ID. Every type carrying
// such an implementation is declared in internal/dagger/core, so this only
// has to forward.
func SetMarshalContext(ctx context.Context) {
	core.SetMarshalContext(ctx)
}

type Client struct {
	*core.Query
	client graphql.Client
}

var dag *Client

func init() {
	gqlClient := getClientParams()
	dag = &Client{
		Query:  core.NewQuery(gqlClient),
		client: core.WrapClient(gqlClient),
	}
}

func Connect() *Client {
	return dag
}

// GraphQLClient returns the underlying graphql.Client
func (c *Client) GraphQLClient() graphql.Client {
	return c.client
}

// QueryBuilder returns the underlying query builder.
func (c *Client) QueryBuilder() *querybuilder.Selection {
	return c.Query.QueryBuilder()
}

func getClientParams() graphql.Client {
	portStr, ok := os.LookupEnv("DAGGER_SESSION_PORT")
	if !ok {
		panic("DAGGER_SESSION_PORT is not set")
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		panic(fmt.Errorf("DAGGER_SESSION_PORT %q is invalid: %w", portStr, err))
	}

	sessionToken := os.Getenv("DAGGER_SESSION_TOKEN")
	if sessionToken == "" {
		panic("DAGGER_SESSION_TOKEN is not set")
	}

	host := fmt.Sprintf("127.0.0.1:%d", port)

	dialTransport := &http.Transport{
		DialContext: func(_ context.Context, _, _ string) (net.Conn, error) {
			return net.Dial("tcp", host)
		},
	}
	httpClient := &http.Client{
		Transport: roundTripperFunc(func(r *http.Request) (*http.Response, error) {
			r.SetBasicAuth(sessionToken, "")

			// detect $TRACEPARENT set by 'dagger run'
			r = r.WithContext(fallbackSpanContext(r.Context()))

			// propagate span context via headers (i.e. for Dagger-in-Dagger)
			telemetry.Propagator.Inject(r.Context(), propagation.HeaderCarrier(r.Header))

			return dialTransport.RoundTrip(r)
		}),
	}
	return graphql.NewClient(fmt.Sprintf("http://%s/query", host), httpClient)
}

func fallbackSpanContext(ctx context.Context) context.Context {
	if trace.SpanContextFromContext(ctx).IsValid() {
		return ctx
	}
	return telemetry.Propagator.Extract(ctx, telemetry.NewEnvCarrier(true))
}

// TODO: pollutes namespace, move to non internal package in dagger.io/dagger
type roundTripperFunc func(*http.Request) (*http.Response, error)

func (fn roundTripperFunc) RoundTrip(req *http.Request) (*http.Response, error) {
	return fn(req)
}
